import {rapidBuildScenes} from './rapid-build-cases.js';
const delivery='d13-delivery-dependencies', interfaces='d13-interface-contracts', acceptance='d13-commissioning-complete-paths';
const c=(key,label,options)=>({key,label,options});
const s=(id,label,title,reference,objective,explanation,extra={})=>({id,label,title,reference,objective,pedagogical_role:'mechanism',explanation:[explanation],...extra});
export const learningContract=Object.freeze({driving_question:'How does a design become a tested, usable service?',fixed_boundary:'A 20 MW IT phase in ten 2 MW zones, ending at integrated service acceptance.',changed_variable:'Delivery dependencies, manufacturing release, rack density and acceptance scope.',primary_payoff:'Release work against approved interfaces and count complete accepted paths.',misconception:'Unchanged total MW means unchanged interfaces and delivery dates.',closing_question:'Which packages can proceed after a late rack change, and what releases the rest?'});
export const initialState={intervention:'baseline',factoryWeeks:6,approvalWeek:0,factorySlotWeek:0,boundary:'electrical',rackKW:200,action:'unconfirmed',test:'failure',coolingStart:21,electrical:false,hydraulic:false,geometry:false,logistics:false,controls:false,resources:false,diagnosis:'',showDiagnosis:false};
export const scenes=[
 s('delivery-purpose','Design, procurement and commissioning','How does a design become a usable service?',delivery,'D13.1','The endpoint is an accepted service path. Follow a 20 MW IT phase through dependencies, changed interfaces and acceptance.',{pedagogical_role:'problem'}),
 s('hardware-prices-meme','AI demand and hardware prices','AI demand and hardware prices',delivery,'D13.1','User-supplied hardware-price meme retained from the retired storage deck.',{pedagogical_role:'transition',imageOnly:true}),
 s('service-requirements','Define the finish','Define the service before ordering its equipment.',interfaces,'D13.2','The owner requirement states intended behavior; the design basis explains how the system meets it; acceptance makes it observable. Ten 2 MW zones require electrical, thermal and information paths to the same racks.'),
 s('delivery-paths','Delivery dependencies','Acceptance waits for the last required path.',delivery,'D13.1','Requirements 2 weeks; electrical procurement 18 and installation 3; cooling procurement 10 and installation 4; utility readiness week 16. Integration 4 after all predecessors. Electrical ready week 23, acceptance week 27. Resources available; continuous weeks.'),
 s('critical-path','Which delay matters?','Earlier delivery helps when it advances acceptance.',delivery,'D13.1','Baseline 27; cooling four weeks faster still 27; electrical four weeks faster 23; cooling eight weeks later 28; utility ready week 30 gives 34. Installation and test resources must be available at the changed dates.',{pedagogical_role:'comparison',controls:[c('intervention','Change one input',[['baseline','Baseline'],['cooling-fast','Cooling −4 wk'],['electrical-fast','Electrical −4 wk'],['cooling-late','Cooling +8 wk'],['utility-late','Utility → wk 30']])]}),
 s('epc-and-prefab','Responsibilities and manufacturing','EPC assigns responsibility. Prefabrication locates the work.',delivery,'D13.2','Engineering, procurement and construction are delivery responsibilities. This example assigns design coordination, purchases, site works and integration to one EPC team. It can choose site assembly, factory modules or both. Actual contracts assign the duties.'),
 s('factory-and-site','Factory and site work','A service module moves assembly into the factory.',delivery,'D13.2','Both routes use manufactured components. Prefabrication assembles distribution, manifolds, internal wiring and controls into transportable frames. The site still delivers access, foundations, utilities, placement, field joints, IT racks and integrated acceptance.'),
 {...rapidBuildScenes.find(item=>item.id==='aws-houdini-prefab'),title:'Project Houdini moves data-hall assembly into factories.',objective:'D13.1'},
 s('parallel-schedules','Overlap the work','Factory work can run while the site is prepared.',delivery,'D13.1','Week zero means approved interfaces and available components. Site enabling 8 weeks; site assembly 6; factory assembly initially 6; transport 1; connections 2; acceptance 2. Site-built 16; prefab max(factory+1,8)+2+2, initially 12. These exercise durations do not describe Houdini.',{pedagogical_role:'comparison',controls:[c('factoryWeeks','Factory assembly + checks',[[6,'6 weeks'],[9,'9 weeks'],[12,'12 weeks']])]}),
 s('manufacturing-release','Freeze the interfaces','A factory release commits the interfaces it consumes.',interfaces,'D13.2','Approve ratings, dimensions, connection locations, signal definitions and drawing revisions before cutting or assembling affected work. Release independent packages only when approved boundaries establish independence. Design approval does not reserve factory capacity.'),
 s('module-transport','Transport and placement','The module must fit the route and the installation.',delivery,'D13.2','Use actual shipping dimensions, mass, center of gravity, lifting points, route limits and placement access. In this exercise IT racks are installed after shipment; doubled installed rack mass does not automatically double module shipping mass.'),
 s('compass-package','Siemens and Compass','One factory package still has site interfaces.',interfaces,'D13.2','Siemens and Compass co-developed a medium-voltage skid with 8DJH 36 switchgear and a transformer. The factory photo shows switchgear, not the transformer. The responsibility questions are teaching prompts, not claims about Compass contractual scope.',{pedagogical_role:'case-study',sources:['https://www.siemens.com/en-us/company/insights/compass-datacenters-case-study/']}),
 s('interface-owner','Own the joint','Give each connection an accountable integration owner.',interfaces,'D13.2','The exercise assigns closure to the EPC interface manager. Module supplier owns internal assemblies; site contractor owns field connections; design leads approve adequacy. Both technical sides agree the joint, then commissioning verifies the installed result.',{controls:[c('boundary','Inspect a boundary',[['electrical','Electrical'],['coolant','Coolant'],['structure','Base and joints'],['controls','Controls']])]}),
 s('rack-change','The late rack change','The phase stays at 20 MW. Each rack connection changes.',interfaces,'D13.2','Ten 2 MW zones change from twenty 100 kW racks per zone to ten 200 kW racks. Hold IT duty fixed; auxiliary demand, current, hydraulic pressure, geometry and local loads still require review.',{pedagogical_role:'problem'}),
 s('electrical-interface','Check each electrical branch','Half as many branches does not double their rating.',interfaces,'D13.2','Balanced 480 V three-phase, PF 1, one full-duty supply path. 120.3 A at 100 kW becomes 240.6 A at 200 kW, beyond the old allowable continuous 160 A. Review the revised ratings, one-line, protection and failure states.',{controls:[c('rackKW','Rack duty',[[100,'100 kW'],[200,'200 kW']])]}),
 s('hydraulic-interface','Check flow and pressure','The same total flow can exceed each rack branch.',interfaces,'D13.2','All IT heat enters water, cp 4.18 kJ/(kg·K), rise at most 10 K. 2.39 becomes 4.78 kg/s; old branch limit 3.0. Reused hardware has quadratic pressure-flow behavior: 20 becomes 80 kPa, beyond 60 available. Actual pump and component curves release the redesign.',{controls:[c('rackKW','Rack duty',[[100,'100 kW'],[200,'200 kW']])]}),
 s('spatial-interface','Check the occupied position','An unchanged zone weight can double each support load.',interfaces,'D13.2','The vendor drawing stipulates twice the installed mass on the same four feet, equally shared. Half as many racks preserves zone mass but doubles occupied-position and foot loads. Check supports, anchorage, connection positions, service clearance and replacement routes.'),
 s('release-holds','Release each package','Continue independent work. Release changed work with evidence.',interfaces,'D13.2','Controls represent completed approvals. Electrical and hydraulic fabrication also need coordinated geometry. The logistics checkbox approves the transport plan only; actual shipment still requires factory release. Resources must be confirmed to support the schedule. Service acceptance remains outstanding.',{pedagogical_role:'transfer'}),
 s('approval-delay','Recalculate the date','Late approval consumes the overlap before it delays the finish.',delivery,'D13.1','Factory 6 weeks; transport 1; site ready 8; connections 2; acceptance 2. Approval week 0 gives finish 12; approval 3 gives 14; approval 5 gives 16. Start waits for the available factory slot. Site-built remains 16 while approvals precede week 8.',{controls:[c('approvalWeek','Interfaces approved',[[0,'Week 0'],[3,'Week 3'],[5,'Week 5']]),c('factorySlotWeek','Factory capacity available',[[0,'On approval'],[7,'Week 7']])]}),
 s('controls-interface','Prove the action path','An alarm is only the start of the response.',interfaces,'D13.2','A cooling-fault signal must identify the rack, have defined units and freshness, reach an authorized action and provide observed confirmation. Remap alarms, circuits and reduction groups for the revised racks. The example does not prescribe a live operating procedure.',{controls:[c('action','Load reduction request',[['unconfirmed','No response confirmed'],['confirmed','Response measured']])]}),
 s('factory-acceptance','Factory acceptance tests','A factory test covers the assembly that was tested.',acceptance,'D13.3','FAT means factory acceptance test. It can check internal wiring, plumbing and controls against agreed criteria. Site cables, coolant joints and the final load path remain outside a test where those objects are absent. Shipment release and service acceptance have different evidence.'),
 s('site-checks','Installation and functional checks','Check the connected installation before the integrated test.',acceptance,'D13.3','Receipt and installation records establish installed configuration, connections and pre-functional checks. Check electrical connections and settings; fluid specification, cleanliness, leak/pressure integrity and measured flow; sensor and command mappings. Functional tests then exercise each connected subsystem.'),
 s('integrated-tests','Integrated acceptance','Test normal duty, failures, maintenance and recovery.',acceptance,'D13.4','Define observable requirements, measurement points and stop/accept criteria before execution. Four scenarios couple electrical, cooling, information and controls. Facilities test loads and application tests establish different evidence.',{controls:[c('test','Acceptance scenario',[['normal','Normal duty'],['failure','Cooling failure'],['maintenance','Maintenance'],['recovery','Recovery']])]}),
 s('accepted-paths','Count complete paths','The accepted systems must reach the same racks.',acceptance,'D13.3','Separate 100-position exercise: electrical A01–A80, cooling A21–A100, network A01–A60. Intersection 40 racks at 100 kW = 4 MW accepted envelope, assuming all other criteria met. Cooling extended to A01 gives 60 racks and 6 MW.',{controls:[c('coolingStart','Cooling acceptance',[[21,'A21–A100'],[1,'A01–A100']])]}),
 s('phase-boundary','Build beside an operating phase','A new phase can change a shared operating system.',acceptance,'D13.4','Teaching topology: A and future B share upstream plant and controls. Define live/construction boundaries, isolation ownership, shared capacity and required retests before connecting B. A prior acceptance record does not automatically accept a changed shared configuration.'),
 s('handover-records','Handover','Hand over the configuration that passed the tests.',acceptance,'D13.4','Preserve as-built topology, asset IDs, protection and controls versions, results, issue dispositions and operating limits. Provide procedures, maintenance ownership and training. Every open issue needs an affected path and explicit owner decision.'),
 s('release-decision','Chapter 13 knowledge check','The electrical and cooling designs pass. What can proceed?',interfaces,'D13.2','Revised electrical/hydraulic designs pass. Revised geometry, transport plan and replacement factory slot are missing. Continue independent site work; release approved packages only where independent of unresolved geometry. Hold frames, shared joints, shipment and unconditional dates. Request coordinated drawings, transport evidence and confirmed resources.',{pedagogical_role:'transfer'}),
];

export function resolveProcurementScene(hash){
 const id=hash;
 const index=scenes.findIndex(scene=>scene.id===id);
 return index<0?0:index;
}
